{"content":"import type { BallId, Vec3Tuple } from '../types';
import { BALL_RADIUS, HALF_LENGTH, FOOT_SPOT_Z } from './table';

// Standard billiard ball colors
export const BALL_COLORS: Record<BallId, string> = {
  0: '#FFFFFF',  // Cue ball - white
  1: '#FFD700',  // Yellow (solid)
  2: '#0000FF',  // Blue (solid)
  3: '#FF0000',  // Red (solid)
  4: '#800080',  // Purple (solid)
  5: '#FF8C00',  // Orange (solid)
  6: '#006400',  // Green (solid)
  7: '#8B0000',  // Maroon (solid)
  8: '#000000',  // Black (eight ball)
  9: '#FFD700',  // Yellow (stripe)
  10: '#0000FF', // Blue (stripe)
  11: '#FF0000', // Red (stripe)
  12: '#800080', // Purple (stripe)
  13: '#FF8C00', // Orange (stripe)
  14: '#006400', // Green (stripe)
  15: '#8B0000', // Maroon (stripe)
};

// Triangle rack layout (standard 8-ball formation)
// Row 0: 1 ball, Row 1: 2 balls, ... Row 4: 5 balls
// 8-ball must be in center (row 2, position 1)
// One solid and one stripe in bottom corners
const RACK_ORDER: BallId[] = [1, 9, 2, 10, 8, 11, 3, 14, 6, 15, 4, 12, 7, 13, 5];

export function getRackPositions(): Record<BallId, Vec3Tuple> {
  const positions: Record<number, Vec3Tuple> = {};
  const spacing = BALL_RADIUS * 2.05; // slight gap to prevent initial overlap
  let ballIndex = 0;

  for (let row = 0; row < 5; row++) {
    const ballsInRow = row + 1;
    const rowZ = FOOT_SPOT_Z + row * spacing * Math.cos(Math.PI / 6);
    for (let col = 0; col < ballsInRow; col++) {
      const xOffset = (col - (ballsInRow - 1) / 2) * spacing;
      const x = xOffset;
      const y = BALL_RADIUS;
      const z = rowZ;
      positions[RACK_ORDER[ballIndex]] = [x, y, z];
      ballIndex++;
    }
  }

  // Cue ball at head position
  positions[0] = [0, BALL_RADIUS, -HALF_LENGTH * 0.4];

  return positions as Record<BallId, Vec3Tuple>;
}

export function getBallColor(id: BallId): string {
  return BALL_COLORS[id];
}","end_line":55,"start_line":0,"total_lines":56}

