import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error('Root element not found');
}

createRoot(rootElement).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

import { useState } from 'react';

/**
 * Root component for the 3D 8-Ball Pool Game.
 *
 * Architecture:
 *   App
 *   ├── Scene (R3F Canvas) — to be added in Phase 3
 *   │   ├── PhysicsWorld — to be added in Phase 4
 *   │   ├── Table — to be added in Phase 3
 *   │   ├── Balls — to be added in Phase 3
 *   │   ├── CueStick — to be added in Phase 6
 *   │   └── AimLine — to be added in Phase 6
 *   └── GameUI (HTML overlay) — to be added in Phase 7
 */
function App() {
  const [ready] = useState(true);

  return (
    <div
      style={{
        width: '100vw',
        height: '100vh',
        background: '#1a1a2e',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontFamily: 'system-ui, -apple-system, sans-serif',
      }}
    >
      {ready ? (
        <div style={{ textAlign: 'center', color: '#e0e0e0' }}>
          <h1 style={{ fontSize: '2rem', marginBottom: '0.5rem' }}>
            🎱 8-Ball Pool
          </h1>
          <p style={{ color: '#888', fontSize: '0.9rem' }}>
            Project scaffolded — components will be added in upcoming phases.
          </p>
        </div>
      ) : null}
    </div>
  );
}

export default App;

